// Extrai os dados do pacote gerado pelo pub_rs
const payload = $input.first().json;

return {
  json: {
    client: payload.client,
    brand: payload.brand,
    articleTitle: payload.article.title,
    articleUrl: payload.article.url,
    linkedinPost: payload.copies.linkedin.post,
    linkedinComment: payload.copies.linkedin.firstComment,
    instagramPost: payload.copies.instagram.post,
    instagramComment: payload.copies.instagram.firstComment,
    twitterThread: payload.copies.twitter.thread,
    threadsPost: payload.copies.threads.post,
    facebookPost: payload.copies.facebook.post,
    image16x9: payload.images.find(img => img.format === 'linkedin_twitter_facebook_16x9')?.files?.jpg,
    image4x5: payload.images.find(img => img.format === 'instagram_feed_portrait_4x5')?.files?.jpg,
    image9x16: payload.images.find(img => img.format === 'instagram_stories_reels_9x16')?.files?.jpg
  }
};
